import{_ as t,o as a,c as s,a3 as n}from"./chunks/framework._uRL7xNg.js";const u=JSON.parse('{"title":"What is LazyAPI?","description":"","frontmatter":{},"headers":[],"relativePath":"introduction.md","filePath":"introduction.md","lastUpdated":1795474269000}'),i={name:"introduction.md"};function r(o,e,l,c,d,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="what-is-lazyapi" tabindex="-1">What is LazyAPI? <a class="header-anchor" href="#what-is-lazyapi" aria-label="Permalink to &quot;What is LazyAPI?&quot;">​</a></h1><blockquote><p>OpenAPI-driven API exploration, testing and automation from the terminal, for humans and AI agents.</p></blockquote><p>LazyAPI uses your OpenAPI spec as the single source of truth, so there are no collections to keep in sync. You can:</p><ul><li>explore the API in a terminal UI;</li><li>send requests and see every response checked against the spec;</li><li>write tests in JavaScript or TypeScript;</li><li>run everything in CI;</li><li>let an AI agent drive it through MCP or the CLI&#39;s JSON output.</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>             ┌── TUI ─── explore, send, edit, debug                    (humans)</span></span>
<span class="line"><span>OpenAPI  ────┼── CLI ─── run · send · describe · validate              (CI, scripts)</span></span>
<span class="line"><span>+ .lazyapi/  └── MCP ─── list · describe · send · write_test · run     (agents)</span></span>
<span class="line"><span>                  │</span></span>
<span class="line"><span>                  └─ every response is checked: request · status · contract · your tests</span></span></code></pre></div><h2 id="why" tabindex="-1">Why? <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why?&quot;">​</a></h2><p>Most API tools make you recreate what is already in the OpenAPI document: endpoints, parameters, bodies, auth. Then the copy drifts from the spec. LazyAPI reads the spec directly, keeps tests and environments in a <code>.lazyapi/</code> directory next to it, and validates every exchange against it.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>OpenAPI-first</strong>: load any OpenAPI 3.x spec and browse its operations immediately.</li><li><strong>Checked exchanges</strong>: request, status, contract and your tests, on every send.</li><li><strong>Interactive TUI</strong>: request list grouped by tag, editor, response view with jq, history and diff, runner.</li><li><strong>CLI for CI</strong>: <code>run</code>, <code>send</code>, <code>describe</code>, <code>validate</code>, <code>mock</code>, <code>import</code>; JSON, JUnit and TAP reports.</li><li><strong>Scripts</strong>: JavaScript/TypeScript tests and flows, URL imports pinned in a lock file, <code>before</code>/<code>after</code> hooks, fake data.</li><li><strong>Authentication</strong>: Basic, Bearer, API key and OAuth2 (client credentials and password, tokens cached).</li><li><strong>Environments</strong>: named environments in <code>.lazyapi/config.yml</code>, variables committed, secrets git-ignored.</li><li><strong>Agents</strong>: an MCP server confined to a root directory.</li><li><strong>Portable</strong>: a single binary for Linux, macOS and Windows.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/installation">Install LazyAPI</a></li><li><a href="/getting-started">Getting started</a> with the bundled example and the mock server</li><li><a href="/tui/">The TUI</a> and its <a href="/tui/keyboard-shortcuts">keyboard shortcuts</a></li><li><a href="/cli/">The CLI reference</a></li></ul>`,11)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
